test("Kind from invalid string", () => {
  const parsed = OurStringification.kindFromString(
    "invalid-literal"
  );

  expect(parsed).toBeNull();
});

test("Kind invalid literal to string", () => {
  // The number 9007199254740991 is the maximum safe integer.
  const invalidLiteral = <OurTypes.Kind>9007199254740991;

  expect(OurStringification.kindToString(invalidLiteral)).toBeNull();
  expect(() => OurStringification.mustKindToString(invalidLiteral)).toThrow();
});

